import pandas as pd
import numpy as np

def run(inputs: dict[str, pd.DataFrame]) -> dict[str, pd.DataFrame]:
    target_state = inputs["target_state"].copy()
    cdc_events = inputs["cdc_events"].copy()

    # Ensure proper dtypes
    target_state["order_id"] = target_state["order_id"].astype("int64")
    target_state["status"] = target_state["status"].astype("str")
    target_state["amount"] = target_state["amount"].astype("float64")
    target_state["last_seq"] = target_state["last_seq"].astype("int64")

    cdc_events["seq"] = cdc_events["seq"].astype("int64")
    cdc_events["order_id"] = cdc_events["order_id"].astype("int64")
    cdc_events["op"] = cdc_events["op"].astype("str")
    cdc_events["status"] = cdc_events["status"].astype("str")
    cdc_events["amount"] = cdc_events["amount"].astype("float64")

    # Step 1: Remove duplicate events (keep first occurrence of each seq)
    cdc_events = cdc_events.drop_duplicates(subset=["seq"], keep="first").reset_index(drop=True)

    # Step 2: Sort events by seq (the only trusted ordering)
    cdc_events = cdc_events.sort_values("seq").reset_index(drop=True)

    # Step 3: Apply replay guard and filter events
    # For each order, skip events where seq <= last_seq in target_state
    target_state_dict = {}
    if len(target_state) > 0:
        for _, row in target_state.iterrows():
            target_state_dict[row["order_id"]] = row["last_seq"]

    filtered_events = []
    for _, event in cdc_events.iterrows():
        order_id = event["order_id"]
        seq = event["seq"]

        # Replay guard: skip if order exists in target_state and seq <= last_seq
        if order_id in target_state_dict and seq <= target_state_dict[order_id]:
            continue

        filtered_events.append(event)

    if filtered_events:
        filtered_events = pd.DataFrame(filtered_events).reset_index(drop=True)
    else:
        filtered_events = pd.DataFrame(columns=cdc_events.columns)

    # Step 4: Build new state by applying events in order
    state = {}
    if len(target_state) > 0:
        for _, row in target_state.iterrows():
            state[row["order_id"]] = {
                "status": row["status"],
                "amount": row["amount"],
                "last_seq": row["last_seq"]
            }

    last_op = {}  # Track last operation (op) and seq for each order for tombstones

    for _, event in filtered_events.iterrows():
        order_id = event["order_id"]
        op = event["op"]
        seq = event["seq"]
        status = event["status"]
        amount = event["amount"]

        if op == "D":
            # Delete: remove the row
            if order_id in state:
                del state[order_id]
            last_op[order_id] = ("D", seq)

        elif op == "I" or op == "U":
            # Insert or Update
            if order_id not in state:
                # Create new row
                state[order_id] = {
                    "status": status,
                    "amount": amount,
                    "last_seq": seq
                }
            else:
                # Update existing row
                state[order_id]["status"] = status
                # For Update, NULL amount leaves existing amount unchanged
                if pd.notna(amount) or op == "I":
                    state[order_id]["amount"] = amount
                state[order_id]["last_seq"] = seq

            last_op[order_id] = (op, seq)

    # Step 5: Build new_state DataFrame
    new_state_rows = []
    for order_id, record in state.items():
        new_state_rows.append({
            "order_id": order_id,
            "status": record["status"],
            "amount": record["amount"],
            "last_seq": record["last_seq"]
        })

    if new_state_rows:
        new_state = pd.DataFrame(new_state_rows)
    else:
        new_state = pd.DataFrame(columns=["order_id", "status", "amount", "last_seq"])

    # Ensure dtypes
    new_state["order_id"] = new_state["order_id"].astype("int64")
    new_state["status"] = new_state["status"].astype("str")
    new_state["amount"] = new_state["amount"].astype("float64")
    new_state["last_seq"] = new_state["last_seq"].astype("int64")

    # Step 6: Build tombstones
    # Include orders that had a row in target_state or were created in this batch
    # and whose last applied event is a 'D'
    tombstone_rows = []
    for order_id, (last_op_type, last_seq) in last_op.items():
        if last_op_type == "D":
            tombstone_rows.append({
                "order_id": order_id,
                "deleted_seq": last_seq
            })

    if tombstone_rows:
        tombstones = pd.DataFrame(tombstone_rows)
    else:
        tombstones = pd.DataFrame(columns=["order_id", "deleted_seq"])

    # Ensure dtypes
    tombstones["order_id"] = tombstones["order_id"].astype("int64")
    tombstones["deleted_seq"] = tombstones["deleted_seq"].astype("int64")

    return {
        "new_state": new_state,
        "tombstones": tombstones
    }
